import{_ as t,o as n,c as r,a3 as d}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"ioBroker: automatische Rollenzuordnung","description":"","frontmatter":{},"headers":[],"relativePath":"projects/mqtt-client/iobroker-roles.md","filePath":"projects/mqtt-client/iobroker-roles.md","lastUpdated":1794652120000}'),i={name:"projects/mqtt-client/iobroker-roles.md"};function a(s,e,o,l,c,u){return n(),r("div",null,[...e[0]||(e[0]=[d(`<h1 id="iobroker-role-mapping" tabindex="-1">ioBroker: automatische Rollenzuordnung <a class="header-anchor" href="#iobroker-role-mapping" aria-label="Permalink to &quot;ioBroker: automatische Rollenzuordnung {#iobroker-role-mapping}&quot;">​</a></h1><p>Das optionale JavaScript gehört zu MQTT-Client <strong>0.1.34</strong> und läuft im ioBroker-JavaScript-Adapter. Es verwendet die übertragenen Metadaten <code>device_class</code> und <code>unit_of_measurement</code>. Es ordnet nur eindeutige Fälle zu; weder MQTT-Werte noch Datentypen, Einheiten, Zugangsdaten oder Rückkanäle werden umgeschrieben.</p><h2 id="settings-persistence-0136" tabindex="-1">Neu in 0.1.36: Einstellungen nach Updates erhalten <a class="header-anchor" href="#settings-persistence-0136" aria-label="Permalink to &quot;Neu in 0.1.36: Einstellungen nach Updates erhalten {#settings-persistence-0136}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Erfolgreicher Neustarttest am 07.11.2026</p><p>Der Nutzer hat nach erneutem Speichern der Einstellungen beim Umstieg auf <strong>0.1.36</strong> die MQTT-Client-App neu gestartet und bestätigt: <strong>Der Messwerte-Haken bleibt gesetzt, die MQTT-Struktur bleibt „Flach mit kurzen Namen“.</strong> Damit ist der praktische Neustarttest erfolgreich. Ein weiterer Versionswechsel wurde dabei nicht geprüft; der praktische Update-Test auf die nächste Version steht noch aus.</p></div><p><strong>Gespeicherte App-Einstellungen bleiben jetzt auch erhalten, wenn der Home-Assistant-Supervisor beim Update seine Optionsdatei neu erzeugt.</strong> Das betrifft insbesondere den Messwerte-Haken und die MQTT-Struktur für neue Entitäten, aber auch die übrigen in der App gespeicherten Einstellungen und Zugangsdaten. Die App sichert sie unabhängig in der privaten Datei <code>/data/mqtt-settings.json</code>. Die MQTT-Pfadzuordnungen bleiben weiterhin in <code>/data/mqtt-routes.json</code>; vorhandene Datenpunkte und VIS-2-Verknüpfungen werden nicht geändert.</p><p><strong>Einmaliger Umstieg von 0.1.35 oder älter:</strong> Vor dem Update die Einstellungen in der App exportieren. Falls sie beim ersten Wechsel bereits zurückgesetzt wurden, die Sicherung nach dem Update wieder importieren oder die beiden Optionen einmal erneut wählen und <strong>Speichern und verbinden</strong> drücken. Schon verlorene Einstellungen können nicht zuverlässig rekonstruiert werden; zusätzliche Messwerte werden nicht ungefragt aktiviert.</p><p>Die Einstellungen bevorzugt in der App ändern. Tatsächlich geänderte Supervisor-Konfigurationswerte werden beim Neustart übernommen; unveränderte Supervisor-Standardwerte setzen App-Auswahlen nicht zurück. Soll eine App-Auswahl ausdrücklich auf ihren Standard zurück, dies in der App wählen und speichern. Die vorhandene Einstellungssicherung bleibt verwendbar und enthält weiterhin keine Passwörter oder privaten TLS-Schlüssel. Der JavaScript-Helfer bleibt <strong>0.1.34</strong>; hierfür muss er nicht erneut ersetzt werden.</p><p>Hintergrund: Der Supervisor verwaltet <code>/data/options.json</code>; für eigene dauerhafte Daten ist das private <code>/data</code>-Verzeichnis vorgesehen. <a href="https://contributors.home-assistant.io/apps/reference/environment/" target="_blank" rel="noreferrer">Offizielle HA-Dokumentation</a>.</p><h2 id="mqtt-layout-0134" tabindex="-1">Neu in 0.1.34: flache MQTT-Pfade nur für neue Entitäten <a class="header-anchor" href="#mqtt-layout-0134" aria-label="Permalink to &quot;Neu in 0.1.34: flache MQTT-Pfade nur für neue Entitäten {#mqtt-layout-0134}&quot;">​</a></h2><p>Unter <strong>Übertragung und TLS → MQTT-Struktur für neue Entitäten</strong> kann <strong>Flach mit kurzen Namen</strong> gewählt werden. Standard bleibt die bisherige Struktur. Danach <strong>Speichern und verbinden</strong>. Die Einstellung gilt für erstmals ausgewählte manuelle Entitäten und neue Label-Mitglieder, einschließlich optionaler Gerätemesswerte.</p><p>Bereits bekannte Entitäten behalten ihre bisherigen Pfade. Die Zuordnung wird dauerhaft in <code>/data/mqtt-routes.json</code> gespeichert und ist in der exportierten Einstellungssicherung enthalten. Auch nach Entfernen und erneutem Auswählen eines Labels, Umbenennen, Neustart oder Update wird derselbe Pfad verwendet. Beim ersten Upgrade werden vorhandene Auswahlen und erfasste Topics als Bestand übernommen; die bestehende Label-Auswahl wird beim ersten erfolgreichen Abgleich gesichert. Diese Datei nicht löschen. Eine Rückstellung auf die bisherige Struktur migriert keine bereits zugeordneten Entitäten.</p><p>Beispiel für neue flache MQTT-Topics:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ha_external/geraet/schalter</span></span>
<span class="line"><span>ha_external/geraet/schalter_set</span></span>
<span class="line"><span>ha_external/geraet/schalter_attribute/device_class</span></span>
<span class="line"><span>ha_external/geraet/energie</span></span>
<span class="line"><span>ha_external/geraet/leistung</span></span>
<span class="line"><span>ha_external/geraet/licht_brightness</span></span>
<span class="line"><span>ha_external/geraet/licht_brightness_set</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Alte Topics wie <code>ha_external/geraet/switch/state</code> und <code>…/switch/set</code> bleiben parallel gültig. Vergebene kurze Namen werden bei Kollisionen eindeutig ergänzt. Vorhandene Datenpunkte, Werte, Aliase und VIS-2-Verknüpfungen werden weder umbenannt noch gelöscht.</p><p><strong>Vor Aktivierung den vollständigen JavaScript-Helfer 0.1.34 installieren und eigene Einstellungen übernehmen.</strong> Er liest beide MQTT-Strukturen anhand des übertragenen Auswahlkatalogs mit exakten Status- und Rückkanalpfaden. Erst Vorschau prüfen, dann <code>mode: &#39;apply&#39;</code>. Ältere Helfer erkennen die neuen flachen MQTT-Pfade nicht. <code>virtualLayout: &#39;flat&#39;</code> ist davon unabhängig: Diese Helferoption bestimmt nur die Darstellung unter <code>0_userdata.0.ugso_mqtt</code>. Die bisherigen manuellen Rollen und Verknüpfungen bleiben geschützt.</p><h2 id="enable-device-readings" tabindex="-1">Wichtig: Zusätzliche Gerätemesswerte ausdrücklich aktivieren <a class="header-anchor" href="#enable-device-readings" aria-label="Permalink to &quot;Wichtig: Zusätzliche Gerätemesswerte ausdrücklich aktivieren {#enable-device-readings}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Wichtig: Zusätzliche Gerätemesswerte ausdrücklich aktivieren</p><p><strong>Ein Label allein aktiviert die zusätzlichen Messwerte nicht.</strong> Unter <strong>Übertragung und TLS</strong> muss der Haken <strong>„Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen“</strong> gesetzt und anschließend <strong>„Speichern und verbinden“</strong> gedrückt werden. Ohne diesen Haken werden Energie, Spannung, Strom und Leistung nicht automatisch zum gelabelten Schalter ergänzt. Bereits manuell ausgewählte Werte bleiben davon unabhängig.</p></div><p>Erfasst werden unterstützte und in HA aktivierte Sensoren mit derselben HA-Gerätezuordnung, sofern vorhanden. Es werden keine Messwerte erzeugt, die das Gerät nicht bereitstellt. <strong>„Zugehörige Messwerte prüfen“</strong> zeigt Erkennung und Ausschlussgründe. Schaltwerte haben Vorrang; Messwerte dürfen verzögert folgen.</p><h2 id="javascript-vis2-helper" tabindex="-1">Besonders für VIS 2: der ioBroker-JavaScript-Helfer <a class="header-anchor" href="#javascript-vis2-helper" aria-label="Permalink to &quot;Besonders für VIS 2: der ioBroker-JavaScript-Helfer {#javascript-vis2-helper}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Besonders für VIS 2: der ioBroker-JavaScript-Helfer</p><p>Das mitgelieferte <strong>JavaScript wird im ioBroker-JavaScript-Adapter ausgeführt, nicht in Home Assistant</strong>. Es legt virtuelle Datenpunkte unter <code>0_userdata.0.ugso_mqtt</code> an: <strong>ein Datenpunkt pro Wert für Anzeige und Bedienung</strong>, obwohl MQTT getrennte <code>state</code>- und <code>set</code>-Topics verwendet. Unterstützte Schalter und Light-Werte erhalten den passenden Rückkanal; Messwerte bleiben lesend. Anhand geeigneter HA-Metadaten werden Datentypen, Einheiten und eindeutige Rollen zugeordnet. Eine Schaltanforderung ist erst nach tatsächlicher HA-Rückmeldung bestätigt.</p><p><strong>Zuerst Vorschau prüfen, dann <code>mode: &#39;apply&#39;</code> einstellen.</strong> In der Vorschau werden nur fehlende eigene Basisordner/Sicherungsdatenpunkte angelegt; die virtuellen VIS-2-Werte entstehen im Anwendungsmodus. Für die Anlage muss <strong>setObject</strong> in den Adaptereinstellungen erlaubt sein. Bestehende Werte und manuell gesetzte Rollen bleiben geschützt. Die HA-App und der Helfer liegen für diese Erweiterung bei <strong>0.1.33</strong>. Für die flache Struktur den vollständigen Helfer in ioBroker ersetzen; ein App-Update allein genügt dafür nicht. Ohne Helfer ist die reine MQTT-Übertragung weiterhin nutzbar.</p></div><h2 id="flat-layout-0133" tabindex="-1">Neu in 0.1.33: flache VIS-2-Struktur mit kurzen Namen <a class="header-anchor" href="#flat-layout-0133" aria-label="Permalink to &quot;Neu in 0.1.33: flache VIS-2-Struktur mit kurzen Namen {#flat-layout-0133}&quot;">​</a></h2><p><strong>Den vollständigen JavaScript-Helfer 0.1.33 ersetzen und eigene Einstellungen übernehmen.</strong> Im Einstellungsblock wählt <code>virtualLayout: &#39;nested&#39;</code> die bisherige Struktur (Standard); <code>virtualLayout: &#39;flat&#39;</code> legt kurze Datenpunkte direkt unter dem Geräteordner an, etwa <code>schalter</code>, <code>energie</code>, <code>leistung</code>, <code>spannung</code>, <code>stromstaerke</code>. Bei Lampen kommen passende Werte wie <code>helligkeit</code>, <code>farbe</code>, <code>effekt</code> und <code>farbtemperatur</code> hinzu. Gleichartige oder belegte Namen erhalten eindeutige Zusätze wie <code>leistung_2</code>; einmal vergebene Zuordnungen bleiben im Sicherungsjournal erhalten.</p><p>Zuerst im Vorschaumodus prüfen, anschließend <code>mode: &#39;apply&#39;</code> wählen. Ein Layoutwechsel löscht oder verschiebt keine vorhandenen Datenpunkte. Bereits vom Helfer angelegte alte und neue IDs werden weiter aktualisiert und behalten ihre freigegebenen Rückkanäle; vorhandene VIS-2-Verknüpfungen können bleiben. Deshalb bleiben alte Ordner zunächst auch sichtbar. Fremde Objekte und manuelle Rollen werden nicht überschrieben, MQTT-Topics bleiben unverändert. Zur Rückkehr die Option mit dem neuen Helfer auf <code>nested</code> stellen; die alte Helferdatei 0.1.27 kann Journale mit flachen Einträgen nicht lesen.</p><h2 id="readings-highlight-0132" tabindex="-1">Neu in 0.1.32: zusätzliche Messwerte deutlich markieren <a class="header-anchor" href="#readings-highlight-0132" aria-label="Permalink to &quot;Neu in 0.1.32: zusätzliche Messwerte deutlich markieren {#readings-highlight-0132}&quot;">​</a></h2><p>Die Option <strong>„Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen“</strong> ist gelb hervorgehoben. Die Markierung aktiviert den Haken nicht: Gewünschte Auswahl setzen und <strong>„Speichern und verbinden“</strong> drücken. Bestehende Einstellungen bleiben erhalten. TLS und Zertifikate sind weiterhin separat einklappbar.</p><h2 id="tls-0131" tabindex="-1">Neu in 0.1.31: TLS und Zertifikate separat einklappen <a class="header-anchor" href="#tls-0131" aria-label="Permalink to &quot;Neu in 0.1.31: TLS und Zertifikate separat einklappen {#tls-0131}&quot;">​</a></h2><p><strong>TLS und Zertifikate</strong> ist jetzt ein eigener, per Maus und Tastatur bedienbarer Klappbereich. Die Schaltfläche zeigt auch geschlossen, ob TLS ausgewählt ist. Beim Auf-/Zuklappen werden weder TLS noch gespeicherte Zertifikate oder Zugangsdaten verändert. Nach Laden und Speichern bleibt der Bereich geschlossen; Übertragungseinstellungen und die beiden Aktionsschaltflächen bleiben sichtbar. Der <a href="/blog/snippets/iobroker-blockly#mqtt-vis2-helper">neue Blogeintrag zum JavaScript-Helfer</a> erklärt Zweck, Einrichtung, Status/Rückkanal und Sicherung und enthält das vollständige unveränderte Skript 0.1.27 mit Kopierbutton und Download.</p><h2 id="credentials-0130" tabindex="-1">Neu in 0.1.30: Zugangsdaten einklappen <a class="header-anchor" href="#credentials-0130" aria-label="Permalink to &quot;Neu in 0.1.30: Zugangsdaten einklappen {#credentials-0130}&quot;">​</a></h2><p><strong>Zugangsdaten</strong> besitzt jetzt eine eigene Auf-/Zuklapp-Schaltfläche, auch per Tastatur bedienbar. Bei vorhandenem Broker bleiben IP, Port, Benutzername und Passwort nach Laden und Speichern eingeklappt. Fehlen Pflichtangaben, wird der Bereich zur Eingabe geöffnet. <strong>Übertragung und TLS</strong>, <strong>Speichern und verbinden</strong> und <strong>Aktuell übertragene Werte</strong> bleiben sichtbar. Einstellungen und Zugangsdaten werden nicht verändert. Die Priorisierung aus 0.1.29 und Helfer 0.1.27 bleiben erhalten. Der Nutzer hat die Schalt-Rückmeldung mit ungefähr einer halben Sekunde Verzögerung als erfolgreich bestätigt. Auch die Zigbee-Lampe wurde erfolgreich geprüft: Rückmeldung funktioniert, die Helligkeit folgt HA auf 100 %.</p><h2 id="priority-0129" tabindex="-1">Neu in 0.1.29: Schaltwerte vor Messwerten <a class="header-anchor" href="#priority-0129" aria-label="Permalink to &quot;Neu in 0.1.29: Schaltwerte vor Messwerten {#priority-0129}&quot;">​</a></h2><p><strong>Die HA-MQTT-Client-App auf 0.1.29 aktualisieren; der ioBroker-Helfer 0.1.27 bleibt unverändert.</strong> Schaltzustände, Kontakte und Befehlsrückmeldungen werden vor Messwerten behandelt. Ihre Veröffentlichung wartet nicht auf die Publish-Pause. Bereits laufende Übertragungen werden abgeschlossen; zwischen Nachrichten geben Messwert-/Attributpakete für dringende Zustände und Schaltbefehle nach. Wenn mindestens 32 Ereignisse warten, werden Sensor-Zwischenstände in begrenzten Paketen auf den jeweils letzten Zustand zusammengefasst. Normale Schaltfolgen bleiben erhalten. Zusätzlich liest der Kontrollabgleich auch bei bestehender Live-Verbindung den tatsächlichen HA-Zustand im vorhandenen <code>poll_interval</code> (Standard 5 Sekunden). Unveränderte Werte werden nicht erneut veröffentlicht. <strong>Übertragung und TLS</strong> sowie die <strong>Publish-Pause für Messwerte und Attribute</strong> sind direkt sichtbar; Zugangsdaten bleiben separat einklappbar. Die Statuszeile unterscheidet <strong>Wartend</strong>, <strong>Zusammengefasst</strong>, <strong>HA-Eingang</strong> und den fortlaufenden Zähler <strong>Gesendet</strong>. Bestehende Einstellungen und Werte bleiben erhalten. Für die Prüfung den Kontrollabgleich auf 5 Sekunden lassen und ein unkritisches Relais in HA schalten. Erst eine tatsächliche HA-Rückmeldung führt zu <code>ack: true</code>; die Broker-Übergabe allein genügt nicht. Lokal geprüft, Bestätigung der Verzögerung auf dem Nutzersystem steht noch aus.</p><p>Schalter werden über die Domain <code>switch.*</code> erkannt und benötigen weder Geräteklasse noch Einheit. Lampen verwenden <code>light.*</code>. Die aktivierte automatische Messwertauswahl bleibt auf dieselbe HA-Gerätezuordnung beschränkt. Für Sensoren gilt zuerst <code>device_class</code>; fehlt sie, werden eindeutige Einheiten aus <code>unit_of_measurement</code> wie W/kW/MW, V/mV/kV, A/mA und Wh/kWh/MWh verwendet. Vorhandene Klassen werden nicht überschrieben; ähnliche Namen oder ein mehrdeutiges Prozentzeichen genügen nicht. Unter <strong>Zugehörige Messwerte prüfen</strong> zeigt eine schreibgeschützte Prüfung die erkannten Sensoren und Ausschlussgründe, etwa fehlende Gerätezuordnung, deaktivierte Entität oder ungeeignete Klasse/Einheit. Messwerte dürfen hinter Schaltwerten warten. Einstellungen, Zugangsdaten und bestehende Werte bleiben erhalten.</p><h2 id="live-0128" tabindex="-1">Neu in 0.1.28: HA-Live-Rückmeldungen ohne fremde Ereignisflut <a class="header-anchor" href="#live-0128" aria-label="Permalink to &quot;Neu in 0.1.28: HA-Live-Rückmeldungen ohne fremde Ereignisflut {#live-0128}&quot;">​</a></h2><p>Diese Korrektur betrifft die <strong>MQTT-Client-App in Home Assistant</strong>: auf 0.1.28 aktualisieren und die App neu starten. Der ioBroker-Helfer 0.1.27 kann unverändert bleiben; sein Austausch allein behebt den Empfang von HA-Ereignissen nicht. Bei aktiver Label-Auswahl werden nur noch Ereignisse tatsächlich ausgewählter Entitäten und ihrer aktivierten Gerätemesswerte eingereiht. Ereignisse des übrigen HA-Bestands können die Warteschlange nicht mehr füllen. Wenn Labels oder Gerätezuordnungen geändert werden, lädt der Client frische HA-Zustände. Ältere gepufferte Zustände mit überholtem <code>last_updated</code> werden nach einem Abgleich verworfen; normale zeitlich geordnete Änderungen bleiben erhalten. Der Überlastzähler zählt seit dem App-Start und meldet weiterhin echte Überläufe ausgewählter Ereignisse. Die eingestellte Publish-Pause und alle Zugangsdaten/Auswahlen bleiben erhalten; ein großer erster Abgleich kann weiterhin länger dauern. Nach abgeschlossenem Erstabgleich ein unkritisches Relais in HA schalten und prüfen, ob MQTT und der virtuelle ioBroker-Status zeitnah folgen. Live-Bestätigung auf dem Nutzersystem steht noch aus.</p><h2 id="commands-0127" tabindex="-1">Neu in 0.1.27: Rückkanal ohne Retain <a class="header-anchor" href="#commands-0127" aria-label="Permalink to &quot;Neu in 0.1.27: Rückkanal ohne Retain {#commands-0127}&quot;">​</a></h2><p>Schaltbefehle werden jetzt gezielt über die ioBroker-MQTT-Schnittstelle <code>sendMessage2Client</code> mit <strong><code>retain: false</code></strong> veröffentlicht. Normale Schreibzugriffe auf MQTT-<code>set</code>-Datenpunkte können im Servermodus mit gesetztem Retain-Flag beim Client ankommen. Der HA-Client verwirft solche Befehle weiterhin, damit beim Verbinden keine alten Schaltaufträge ausgeführt werden. Globale Broker-Einstellungen und MQTT-Datenpunktwerte bleiben erhalten. Der Helfer prüft den Befehlstopic gegen den zugehörigen Statustopic und verwendet <code>native.topic</code>, nicht aus Objekt-IDs erratene Pfade. In VIS 2 weiterhin ausschließlich den virtuellen Datenpunkt unter <code>0_userdata.0.ugso_mqtt</code> mit <code>ack: false</code> bedienen und <code>mode: &#39;apply&#39;</code> verwenden. Die Logzeile <code>Command handed to MQTT adapter (retain=false)</code> bestätigt nur die Übergabe; erst ein neuer HA-Status bestätigt den Vorgang. Der rohe MQTT-<code>set</code>-Wert muss dabei nicht wechseln. Keine automatischen Wiederholungen; Fehler oder fehlende HA-Bestätigung bleiben als unbestätigt erkennbar. Für diese Korrektur die vollständige Helferdatei ersetzen und eigene Einstellungen übernehmen.</p><h2 id="setup-0126" tabindex="-1">Neu in 0.1.26: automatische Basisanlage <a class="header-anchor" href="#setup-0126" aria-label="Permalink to &quot;Neu in 0.1.26: automatische Basisanlage {#setup-0126}&quot;">​</a></h2><p>Fehlende eigene Basisordner (<code>virtualRoot</code>, <code>aliasRoot</code>) und beide Sicherungsdatenpunkte (<code>virtualBackupId</code>, <code>backupId</code>) werden jetzt beim Start in <strong>jedem Modus</strong> automatisch angelegt, auch in <code>preview</code> und <code>restore</code>. Vorhandene Ordner, Sicherungen, Werte und manuelle Rollen werden nicht überschrieben. Neue Journale enthalten gültige leere Strukturen. Für die Basisanlage muss <code>setObject</code> in der JavaScript-Instanz auch in der Vorschau erlaubt sein. Fehlende Freigaben oder kollidierende Pfade werden als Fehler gemeldet. Die Vorschau legt keine steuerbaren VIS-2-Datenpunkte an und ändert keine MQTT-Rollen oder Gerätewerte; dafür nach Prüfung <code>mode: &#39;apply&#39;</code> verwenden. Die ereignisgesteuerte Verarbeitung aus 0.1.25 bleibt erhalten.</p><h2 id="fix-0125" tabindex="-1">Korrektur 0.1.25: fehlende Objekte ohne Warnungen <a class="header-anchor" href="#fix-0125" aria-label="Permalink to &quot;Korrektur 0.1.25: fehlende Objekte ohne Warnungen {#fix-0125}&quot;">​</a></h2><p>In JavaScript-Adapter <strong>10.4.10</strong> warnt auch <code>getObject</code> bei fehlenden IDs. Der Helfer prüft jetzt mit <code>existsObject</code> und <code>existsState</code>, bevor er Objekte oder Zustände liest. Das gilt für Journal, optionale Metadaten, Ordner und noch nicht angelegte virtuelle Datenpunkte. Die vorherige Prüfung über <code>getObject</code> allein reichte nicht aus.</p><p>In der Vorschau erscheinen <code>Preview VIS 2</code>-Zeilen, aber es werden nur fehlende Basisordner und Sicherungen angelegt. Für die automatische Anlage nach der Prüfung <code>mode: &#39;apply&#39;</code> setzen. In der JavaScript-Instanz <code>setObject</code> erlauben und <strong>Do not subscribe to all states on start</strong> deaktivieren, weil der Helfer synchron aus den Zustands-Caches liest. Eine abgebrochene eigene Neuanlage kann nach der Freigabe erneut versucht werden; fremde oder bearbeitete Datenpunkte bleiben geschützt.</p><p>MQTT-Client <strong>ab 0.1.24</strong> liefert den benötigten Auswahlkatalog; für diese Korrektur genügt der Austausch der vollständigen Helferdatei. Alte nicht mehr ausgewählte Retain-Topics ohne aktuelle Entitätskennung werden ausgelassen. Fehlende HA-Metadaten werden nicht vom Helfer erfunden. Die Startmeldung nennt jetzt Version und Betriebsmodus.</p><p>Der Helfer bündelt echte MQTT-Änderungen für eine Sekunde. Im virtuellen Modus werden nur die betroffenen Quellen verarbeitet; unveränderte Wiederholungen und fremde Attribute lösen keinen Durchlauf aus. Eine Vollprüfung erfolgt beim Start und bei Änderungen des Auswahlkatalogs oder der Verfügbarkeit. Die Befehls-Zeitprüfung betrifft nur ausstehende Quellen und endet nach Bestätigung oder Zeitablauf. Der Client abonniert pro Entität nur noch den zum Status passenden Rückkanal; alte ioBroker-Objekte werden nicht gelöscht.</p><h2 id="vis2" tabindex="-1">Neu in 0.1.24: ein VIS-2-Datenpunkt für Status und Befehl <a class="header-anchor" href="#vis2" aria-label="Permalink to &quot;Neu in 0.1.24: ein VIS-2-Datenpunkt für Status und Befehl {#vis2}&quot;">​</a></h2><p>Das Skript richtet jetzt automatisch virtuelle Datenpunkte und Ordner unter <code>0_userdata.0.ugso_mqtt</code> ein. Es ist für die APIs des ioBroker-JavaScript-Adapters <strong>10.4.10</strong> ausgelegt. Zuerst <strong>MQTT-Client auf 0.1.24 aktualisieren</strong> und den Client neu verbinden: Der neue Auswahlkatalog bindet Entität, aktuellen Topic-Pfad und Befehlsfreigabe eindeutig zusammen. Alte Retain-Topics dürfen dadurch keine zusätzlichen Steuerungen erzeugen.</p><p>Oben im vollständigen Skript bleiben zunächst diese Einstellungen:</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">outputMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;virtual&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;preview&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mqttRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mqtt.0.ha_external&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualBackupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt_helper.backup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Nach Prüfung der Vorschau auf <code>mode: &#39;apply&#39;</code> wechseln und neu starten. <strong>Sicherungsdatenpunkt, Ordner und neue VIS-2-Datenpunkte werden automatisch angelegt.</strong> Auch die Vorschau legt fehlende Basisordner und Sicherungen an; neue VIS-2-Nutzdatenpunkte benötigen <code>apply</code>. Vorhandene fremde Datenpunkte, Aliase und manuelle Rollen werden nicht überschrieben. Deinen bisherigen Alias, zum Beispiel unter <code>alias.0.HA</code>, musst du nicht entfernen.</p><p>Beispiel: Aus <code>mqtt.0.ha_external.claudia_pc.switch.state</code> und dem zugehörigen <code>mqtt.0.ha_external.claudia_pc.switch.set</code> entsteht <code>0_userdata.0.ugso_mqtt.claudia_pc.switch.state</code>. <strong>Nur diesen virtuellen Datenpunkt in VIS 2 verwenden.</strong></p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Richtung/Funktion</th><th>Verhalten</th></tr></thead><tbody><tr><td>MQTT-Status → VIS 2</td><td>Bestätigter Zustand mit <code>ack: true</code></td></tr><tr><td>VIS-2-Bedienung → MQTT-Befehl</td><td>Nur aktuelle Bedienungen mit <code>ack: false</code> gehen an <code>/set</code></td></tr><tr><td>Schalter</td><td><code>on</code>/<code>off</code> werden virtuell Boolean; zurück werden <code>ON</code>/<code>OFF</code> gesendet</td></tr><tr><td>Helligkeit</td><td>Prozentwert 0–100, Grenzen geprüft</td></tr><tr><td>RGB</td><td>MQTT-JSON-Array ↔ virtuelle Hexfarbe <code>#RRGGBB</code></td></tr><tr><td>Effekt</td><td>Nur Einträge der aktuellen Effektliste</td></tr><tr><td>Farbtemperatur</td><td>Ganze Kelvinzahl innerhalb der aktuellen Grenzen</td></tr><tr><td>Zahlen, Selects und Text</td><td>Vorhandene Grenzen beziehungsweise Optionen geprüft</td></tr><tr><td>Datum, Messwerte und Batterie</td><td>Lesend; vorhandene MQTT-Werte bleiben unverändert</td></tr></tbody></table></div><p>Es gibt keine Schaltbefehle beim Anlegen, Starten oder Neustarten und keine automatische Wiederholung alter Bedienungen. Eine neue HA-Rückmeldung bestätigt den Wert; die Brokerannahme allein ist keine Ausführungsbestätigung. Fehlt eine neue Rückmeldung etwa 30 Sekunden lang, bleibt der Auftrag unbestätigt und erhält Fehlerqualität <code>q: 128</code>. Bei fehlender Auswahl, unbekanntem Wert oder Offline-Zustand bleibt der letzte Wert mit <code>q: 130</code> erhalten. Befehle werden dann gesperrt. Keine Ersatzwerte wie Null oder Aus erfinden.</p><p>Das Journal unter <code>virtualBackupId</code> wird vor jeder Neuanlage gespeichert und geprüft. Es enthält Zuordnungen und Objektdefinitionen, keine MQTT-Zugangsdaten oder aktuellen Messwerte. Vorhandene MQTT-Datenpunkte werden im virtuellen Modus nicht verändert. Bei <code>mode: &#39;restore&#39;</code> bleiben virtuelle Werte und Dashboard-Verknüpfungen erhalten; eigene virtuelle Befehlsdatenpunkte werden schreibgeschützt und die Synchronisierung endet. Danach das Skript stoppen.</p><p>Die bisherige Funktion bleibt über <code>outputMode: &#39;roles&#39;</code> verfügbar. Die folgenden direkten Rollen-/Aliasregeln und deren Wiederherstellung beziehen sich auf diesen Rollenmodus; die Zuordnungstabellen gelten fachlich auch für virtuelle Datenpunkte. <strong>Nur eine Kopie des Helfers gleichzeitig ausführen.</strong> Fehlende optionale Attribute und ein noch nicht angelegtes Journal werden ohne die bisherigen <code>getState</code>-Warnungen behandelt.</p><h2 id="installation" tabindex="-1">Installation und Sicherung <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation und Sicherung {#installation}&quot;">​</a></h2><ol><li>Vorher im ioBroker-Admin die betroffenen MQTT-Objekte einschließlich Zuständen und vorhandenen Skripten exportieren beziehungsweise eine vollständige Sicherung erstellen.</li><li>Im MQTT-Client <strong>ioBroker-/VIS-2-Helfer herunterladen</strong> wählen oder <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/mqtt_client/app/iobroker/ugso-mqtt-role-mapper.js" target="_blank" rel="noreferrer">die Skriptdatei laden</a>.</li><li>Im ioBroker unter <strong>Skripte</strong> ein neues <strong>JavaScript</strong> anlegen und den gesamten Dateiinhalt einfügen. Es genügt ein Skript in einer JavaScript-Instanz.</li><li>Oben <code>mqttRoot</code> auf den eigenen MQTT-Pfad einstellen, zum Beispiel <code>mqtt.0.ha_external</code>. Der Pfad darf keine Platzhalter enthalten.</li><li>Zunächst <code>mode: &#39;preview&#39;</code> beibehalten, starten und das JavaScript-Protokoll prüfen. Die Vorschau legt nur fehlende eigene Basisordner und Sicherungen an.</li><li>Manuell als <code>state</code> verwendete Datenpunkte in <code>excludeIds</code> eintragen. Eine solche manuelle Standardrolle ist von der automatisch vergebenen Rolle nicht unterscheidbar.</li><li>Nach der Kontrolle <code>mode: &#39;apply&#39;</code> setzen und das Skript neu starten. In den Einstellungen der JavaScript-Instanz muss die Verwendung von <code>setObject</code> erlaubt sein. Die Instanz muss die MQTT-Zustände lesen können.</li></ol><p>Vor jeder Änderung wird die ursprüngliche Rolle im JSON-Datenpunkt <code>0_userdata.0.ugso_mqtt_roles.backup</code> gespeichert und die Speicherung bestätigt. Der Datenpunkt enthält keine Zählerwerte oder Zugangsdaten. Bei einem Sicherungsfehler erfolgt keine nachfolgende Rollenänderung. Den Sicherungsdatenpunkt zusätzlich exportieren und nicht löschen.</p><p>Spezialrollen wie <code>date</code>, <code>text</code> oder <code>value.temperature</code> werden nicht ersetzt. Nach einer späteren manuellen Rollenänderung übernimmt das Skript diesen Datenpunkt nicht erneut. Vorhandene Aliase werden nie überschrieben.</p><h2 id="aliases" tabindex="-1">Direkte Rollen und schreibgeschützte Aliase <a class="header-anchor" href="#aliases" aria-label="Permalink to &quot;Direkte Rollen und schreibgeschützte Aliase {#aliases}&quot;">​</a></h2><p>Datum und Zeitstempel erhalten direkt die Rolle <code>date</code>. Der gespeicherte Text und die Schreibrechte bleiben erhalten; auch <code>uptime</code> ist in HA ein Startzeitpunkt, keine Laufzeitdauer.</p><p>Messwert- und Binärsensorrollen sind in ioBroker schreibgeschützt. Ist das MQTT-Original bereits schreibgeschützt, wird nur seine allgemeine Rolle ersetzt. Ist es schreibbar, entsteht stattdessen ein lesender Alias unter <code>alias.0.ugso_mqtt_roles</code>; Rolle und Schreibrechte des MQTT-Originals bleiben erhalten. Den Alias für Visualisierung und Auswertung verwenden. Seine Werte stammen weiterhin aus dem ursprünglichen MQTT-Datenpunkt.</p><p>Das Skript prüft Metadaten und tatsächlichen Werttyp. Aus Gerätenamen oder <code>on</code>/<code>off</code>-Texten werden keine Typen geraten. Fehlende Metadaten, abweichende Einheiten, ungültige Datumswerte und unbekannte Klassen werden ausgelassen. Es erzeugt keine Umrechnungen oder Steuerbefehle. <code>device_class</code> muss übertragen werden, bei Messwerten zusätzlich die Einheit; bei manueller Auswahl diese vorhandenen Attribute mit auswählen. Die Label-Funktion liefert vorhandene Standardattribute automatisch.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>HA-Geräteklasse</th><th>ioBroker-Rolle</th><th>Prüfung</th></tr></thead><tbody><tr><td><code>date</code></td><td><code>date</code></td><td>Gültiges <code>YYYY-MM-DD</code></td></tr><tr><td><code>timestamp</code>, <code>uptime</code></td><td><code>date</code></td><td>ISO-Zeitstempel mit Zeitzone</td></tr></tbody></table></div><h2 id="numeric" tabindex="-1">Umgesetzte numerische Zuordnungen <a class="header-anchor" href="#numeric" aria-label="Permalink to &quot;Umgesetzte numerische Zuordnungen {#numeric}&quot;">​</a></h2><p>Diese Tabelle nennt die tatsächlich akzeptierten Einheiten. Andere Einheiten bleiben unverändert; auch beispielsweise mA oder mV werden nicht stillschweigend umgerechnet.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>HA-Geräteklasse</th><th>ioBroker-Rolle</th><th>Akzeptierte Einheiten</th></tr></thead><tbody><tr><td><code>temperature</code></td><td><code>value.temperature</code></td><td><code>°C</code>, <code>°F</code>, <code>K</code></td></tr><tr><td><code>humidity</code></td><td><code>value.humidity</code></td><td><code>%</code></td></tr><tr><td><code>absolute_humidity</code></td><td><code>value.humidity.absolute</code></td><td><code>g/m³</code>, <code>mg/m³</code></td></tr><tr><td><code>battery</code></td><td><code>value.battery</code></td><td><code>%</code></td></tr><tr><td><code>voltage</code></td><td><code>value.voltage</code></td><td><code>V</code></td></tr><tr><td><code>current</code></td><td><code>value.current</code></td><td><code>A</code></td></tr><tr><td><code>power</code></td><td><code>value.power</code></td><td><code>W</code>, <code>kW</code></td></tr><tr><td><code>energy</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>energy_storage</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>reactive_power</code></td><td><code>value.power.reactive</code></td><td><code>var</code>, <code>kvar</code>, <code>kVar</code></td></tr><tr><td><code>reactive_energy</code></td><td><code>value.energy.reactive</code></td><td><code>varh</code>, <code>kvarh</code>, <code>kVarh</code></td></tr><tr><td><code>frequency</code></td><td><code>value.frequency</code></td><td><code>Hz</code></td></tr><tr><td><code>pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>atmospheric_pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>illuminance</code></td><td><code>value.brightness</code></td><td><code>lx</code>, <code>lux</code></td></tr><tr><td><code>distance</code></td><td><code>value.distance</code></td><td><code>m</code>, <code>km</code>, <code>cm</code>, <code>mm</code>, <code>mi</code>, <code>nmi</code>, <code>yd</code>, <code>ft</code>, <code>in</code></td></tr><tr><td><code>duration</code></td><td><code>value.interval</code></td><td><code>s</code>, <code>ms</code>, <code>h</code>, <code>d</code></td></tr><tr><td><code>wind_speed</code></td><td><code>value.speed</code></td><td><code>m/s</code>, <code>km/h</code>, <code>mph</code>, <code>kn</code></td></tr><tr><td><code>volume_flow_rate</code></td><td><code>value.flow</code></td><td><code>m³/h</code></td></tr><tr><td><code>signal_strength</code></td><td><code>value.rssi</code></td><td><code>dBm</code></td></tr><tr><td><code>aqi</code></td><td><code>value.airquality</code></td><td>—</td></tr><tr><td><code>carbon_dioxide</code></td><td><code>value.co2</code></td><td><code>ppm</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>value.co</code></td><td><code>ppm</code></td></tr><tr><td><code>nitrogen_monoxide</code></td><td><code>value.no</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>nitrogen_dioxide</code></td><td><code>value.no2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>ozone</code></td><td><code>value.o3</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>sulphur_dioxide</code></td><td><code>value.so2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm1</code></td><td><code>value.pm1</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm25</code></td><td><code>value.pm25</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm10</code></td><td><code>value.pm10</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>radon</code></td><td><code>value.rn</code></td><td><code>Bq/m³</code></td></tr><tr><td><code>volatile_organic_compounds</code></td><td><code>value.tvoc</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>volatile_organic_compounds_parts</code></td><td><code>value.tvoc</code></td><td><code>ppb</code></td></tr></tbody></table></div><h2 id="binary" tabindex="-1">Binärsensoren <a class="header-anchor" href="#binary" aria-label="Permalink to &quot;Binärsensoren {#binary}&quot;">​</a></h2><p>Nur bei echten booleschen Werten und passendem Objekttyp. Die üblichen HA-Texte <code>on</code> und <code>off</code> bleiben unverändert und bekommen durch dieses Skript keine boolesche Rolle. Bei <code>battery</code> bedeutet wahr Batterie schwach; bei <code>lock</code> bedeutet wahr entriegelt.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>HA-Geräteklasse</th><th>ioBroker-Rolle</th></tr></thead><tbody><tr><td><code>battery</code></td><td><code>indicator.lowbat</code></td></tr><tr><td><code>connectivity</code></td><td><code>indicator.reachable</code></td></tr><tr><td><code>door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>garage_door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>window</code></td><td><code>sensor.window</code></td></tr><tr><td><code>opening</code></td><td><code>sensor.contact</code></td></tr><tr><td><code>lock</code></td><td><code>sensor.lock</code></td></tr><tr><td><code>motion</code></td><td><code>sensor.motion</code></td></tr><tr><td><code>moisture</code></td><td><code>sensor.alarm.flood</code></td></tr><tr><td><code>smoke</code></td><td><code>sensor.alarm.fire</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>sensor.alarm.co</code></td></tr><tr><td><code>light</code></td><td><code>sensor.light</code></td></tr><tr><td><code>sound</code></td><td><code>sensor.noise</code></td></tr><tr><td><code>problem</code></td><td><code>indicator.error</code></td></tr><tr><td><code>running</code></td><td><code>indicator.working</code></td></tr></tbody></table></div><h2 id="conditional" tabindex="-1">Weitere Zuordnungen aus dem Vergleich <a class="header-anchor" href="#conditional" aria-label="Permalink to &quot;Weitere Zuordnungen aus dem Vergleich {#conditional}&quot;">​</a></h2><p>Im reinen Rollenmodus werden diese Fälle nicht automatisch umgesetzt. Der virtuelle Modus übernimmt die unten genannten Light- und Schaltfunktionen mit den beschriebenen Prüfungen; Füllstand, Verbrauch/Einspeisung und mehrdeutige Messklassen werden weiterhin nicht geraten.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>HA-Klasse/Funktion</th><th>Mögliche Rolle</th><th>Noch erforderlich</th></tr></thead><tbody><tr><td><code>volume_storage</code></td><td><code>value.fill</code></td><td>Tatsächlichen Behälterfüllstand bestätigen</td></tr><tr><td><code>water</code>, <code>gas</code></td><td>Allgemeiner Messwert</td><td>Verbrauch ist kein Füllstand</td></tr><tr><td><code>energy</code></td><td><code>value.energy.consumed</code> / <code>value.energy.produced</code></td><td>Verbrauch/Einspeisung ausdrücklich feststellen</td></tr><tr><td><code>speed</code></td><td><code>value.speed</code></td><td>Nicht pauschal als Windgeschwindigkeit behandeln</td></tr><tr><td><code>moisture</code> als Zahl</td><td>Allgemeiner Messwert</td><td>Nicht mit binärem Wasseralarm verwechseln</td></tr><tr><td>Helligkeitsrückmeldung</td><td><code>value.dimmer</code></td><td>Prozentwert und Light-Funktion bestätigen</td></tr><tr><td>Helligkeitsvorgabe</td><td><code>level.dimmer</code></td><td>Separaten Rückkanal korrekt anbinden</td></tr><tr><td>Schaltzustand</td><td><code>sensor.switch</code></td><td>Booleschen Wert normalisieren</td></tr><tr><td>Schaltbefehl</td><td><code>switch</code> / <code>switch.light</code></td><td><code>/set</code> anbinden; keinen Befehl zur Einrichtung senden</td></tr><tr><td>Farbtemperaturvorgabe</td><td><code>level.color.temperature</code></td><td>Kelvin, Grenzen und Rückkanal</td></tr><tr><td>Effektauswahl</td><td><code>level.effect</code></td><td>Effektliste und Rückkanal</td></tr><tr><td>RGB-Steuerung</td><td><code>level.color.rgb</code></td><td>JSON-Array in Hexfarbe umwandeln</td></tr></tbody></table></div><p>Für <code>occupancy</code>, <code>presence</code>, <code>moving</code>, <code>plug</code>, binäres <code>power</code>, <code>battery_charging</code>, <code>cold</code>, <code>heat</code>, binäres <code>gas</code>, <code>glass_break</code>, <code>safety</code>, <code>tamper</code>, <code>update</code> und <code>vibration</code> wird keine Spezialrolle geraten. Allgemeine <code>sensor</code>-/<code>indicator</code>-Rollen oder eigene Regeln sind möglich, gehören aber nicht zur sicheren Automatik. Auch alle weiteren nicht aufgeführten Klassen bleiben unverändert.</p><h2 id="restore" tabindex="-1">Wiederherstellung <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Wiederherstellung {#restore}&quot;">​</a></h2><p>Skript stoppen, <code>mode: &#39;restore&#39;</code> einstellen und erneut starten. Das Skript stellt nur eigene Rollenänderungen wieder her, wenn die aktuelle Rolle und der Datentyp noch zu seinem Sicherungseintrag passen. Nachträgliche manuelle Rollenänderungen bleiben bestehen. Eigene unveränderte Aliase werden entfernt; bearbeitete oder fremde Aliase bleiben erhalten. MQTT-Originalwerte werden nicht gelöscht.</p><p>Danach das Skript stoppen. Sicherung und Ausnahmeliste aufbewahren. Bereits protokollierte Datenpunkte werden im selben Journal nicht erneut übernommen; ein neuer Durchgang benötigt bewusst einen neuen <code>backupId</code> und bei Aliasen einen freien <code>aliasRoot</code>.</p><p>Lokal mit simulierten ioBroker-APIs auf Vorschau, Sicherungsfehler, Typen, Einheiten, manuelle Änderungen, Aliase und Wiederherstellung geprüft. Noch kein Installationstest auf einem realen ioBroker-System.</p><p><a href="https://www.home-assistant.io/integrations/sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Sensor</a> · <a href="https://www.home-assistant.io/integrations/binary_sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Binary sensor</a> · <a href="https://www.iobroker.com/docs/dev/stateroles.md" target="_blank" rel="noreferrer">ioBroker: State roles</a> · <a href="https://github.com/ioBroker/ioBroker.javascript/blob/v10.4.10/docs/en/javascript.md" target="_blank" rel="noreferrer">ioBroker: JavaScript API</a></p>`,77)])])}const p=t(i,[["render",a]]);export{g as __pageData,p as default};
